const root=$input.first().json||{};
const input=root.input||root;
const status=Number(input.status_code||input.status||0)||null;
const body=String(input.response_body||input.message||'');
const authType=String(input.auth_type||'unknown');
const meta=input.credential_metadata||{};
const checks=[];
const add=(status,name,detail,action=null)=>checks.push({status,name,detail,action});
if(input.secret || input.token || input.api_key || input.password) return [{json:{success:false,component_id:'C6-C',component_version:'v1',error:{code:'SECRET_MATERIAL_NOT_ALLOWED',message:'Pass credential metadata only. Do not pass secret/token/api-key values into C6-C.'},checks:[],next_action:'remove_secret_material_and_retry'}}];
if(meta.expires_at){const exp=Date.parse(meta.expires_at);if(Number.isFinite(exp)) add(exp>Date.now()?'pass':'fail','credential_expiry',exp>Date.now()?'Credential metadata indicates it is not expired.':'Credential metadata indicates it is expired.',exp>Date.now()?null:'refresh_or_reauthenticate');}
if(Array.isArray(meta.required_scopes)&&Array.isArray(meta.granted_scopes)){const missing=meta.required_scopes.filter(s=>!meta.granted_scopes.includes(s));add(missing.length?'fail':'pass','scope_check',missing.length?`Missing scopes: ${missing.join(', ')}`:'Required scopes are present.',missing.length?'grant_required_scopes':null);}
let diagnosis={category:'indeterminate',confidence:'low',reason:'No decisive HTTP/auth signal supplied.'};
if(status===401) diagnosis={category:'invalid_or_expired_credential',confidence:'high',reason:'HTTP 401 indicates authentication was not accepted.'};
else if(status===403) diagnosis={category:'scope_permission_or_resource_access',confidence:'high',reason:'HTTP 403 indicates authenticated access was denied.'};
else if(status===400 && /token|oauth|grant|client/i.test(body)) diagnosis={category:'token_exchange_or_oauth_configuration',confidence:'medium',reason:'HTTP 400 body references token/OAuth/grant/client configuration.'};
else if(status && status>=200 && status<300) diagnosis={category:'credential_path_accepted',confidence:'high',reason:`HTTP ${status} indicates the tested access path was accepted.`};
else if(status===429) diagnosis={category:'credential_likely_valid_rate_limited',confidence:'medium',reason:'Rate limiting commonly occurs after authentication succeeds; verify provider semantics.'};
if(status) add(status>=200&&status<300?'pass':status===401||status===403?'fail':'warn','http_access_signal',`Observed HTTP status ${status}.`,status===401||status===403?'run_c6_c1_after_fix':null);
add(authType==='unknown'?'warn':'pass','auth_type_declared',authType==='unknown'?'auth_type was not supplied.':`Declared auth type: ${authType}.`);
return [{json:{success:true,component_id:'C6-C',component_version:'v1',diagnosis,checks,manual_review_required:checks.some(c=>c.status==='fail')||diagnosis.confidence==='low',next_action:diagnosis.category==='credential_path_accepted'?'continue_integration_health_check':'apply_auth_remediation_then_run_c6_c1',error:null}}];
